PR = r"Представьте в виде степени произведение $%s$."
def prd(e, key, d): return Q(PR % e, key, d)
T("G7_TB_19_418.1", B, [
 prd(r"x^{5}\cdot x^{8}", r"$x^{13}$", [(r"$x^{40}$", r"Ученик перемножил показатели; при умножении степеней показатели складываются."), (r"$x^{3}$", r"Ученик вычел показатели."), (r"$2x^{13}$", r"Ученик сложил степени как подобные слагаемые.")]),
 prd(r"a^{6}\cdot a^{3}", r"$a^{9}$", [(r"$a^{18}$", r"Ученик перемножил показатели."), (r"$a^{3}$", r"Ученик вычел показатели."), (r"$a^{2}$", r"Ученик разделил показатели.")]),
 prd(r"b^{8}\cdot b^{15}", r"$b^{23}$", [(r"$b^{120}$", r"Ученик перемножил показатели."), (r"$b^{7}$", r"Ученик вычел показатели."), (r"$2b^{23}$", r"Ученик сложил степени как подобные слагаемые.")]),
])
T("G7_TB_19_422.1", B, [
 prd(r"x^{4}\cdot x^{3}\cdot x^{2}", r"$x^{9}$", [(r"$x^{24}$", r"Ученик перемножил показатели."), (r"$3x^{9}$", r"Ученик сложил степени как подобные слагаемые."), (r"$x^{8}$", r"Ученик ошибся при сложении показателей.")]),
 prd(r"a\cdot a^{2}\cdot a^{3}", r"$a^{6}$", [(r"$a^{5}$", r"Ученик не учёл, что $a=a^{1}$."), (r"$a^{3}$", r"Ученик взял наибольший показатель вместо суммы показателей."), (r"$3a^{6}$", r"Ученик сложил степени как подобные слагаемые.")]),
 prd(r"y\cdot y^{3}\cdot y^{5}\cdot y^{7}", r"$y^{16}$", [(r"$y^{15}$", r"Ученик не учёл, что $y=y^{1}$."), (r"$y^{105}$", r"Ученик перемножил показатели."), (r"$4y^{16}$", r"Ученик сложил степени как подобные слагаемые.")]),
])
