 Q(QU % r"a^{21}:a", r"$a^{20}$", [(r"$a^{21}$", r"Ученик не учёл, что $a=a^{1}$."), (r"$a^{22}$", r"Ученик сложил показатели."), (r"$1^{20}$", r"Ученик разделил основания $a:a=1$.")]),
